params.command:
$ErrorActionPreference='Stop'
$dirs=@(Get-ChildItem -LiteralPath $env:USERPROFILE -Directory -ErrorAction SilentlyContinue | Where-Object { $_.Name -like 'actions-runner*' } | ForEach-Object {
  $runner=Join-Path $_.FullName '.runner'
  $run=Join-Path $_.FullName 'run.cmd'
  $meta=$null
  if(Test-Path -LiteralPath $runner){ try { $meta=Get-Content -Raw -LiteralPath $runner | ConvertFrom-Json } catch {} }
  [pscustomobject]@{
    path=$_.FullName
    run_exists=(Test-Path -LiteralPath $run)
    configured=(Test-Path -LiteralPath $runner)
    agentId=if($meta){$meta.agentId}else{$null}
    agentName=if($meta){$meta.agentName}else{$null}
  }
})
$listeners=@(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue | Where-Object { $_.Name -eq 'Runner.Listener.exe' } | Select-Object ProcessId,ExecutablePath,CommandLine)
$tasks=@(Get-ScheduledTask -ErrorAction SilentlyContinue | Where-Object { $_.TaskName -match 'runner|heaven' -or $_.TaskPath -match 'runner|heaven' } | Select-Object TaskName,TaskPath,State)
[pscustomobject]@{dirs=$dirs;listeners=$listeners;tasks=$tasks} | ConvertTo-Json -Depth 6 -Compress
